# Since no channel messages were found, try to check if there are any messages at all in the workspace
# We'll check all users' inboxes for messages and see if anyone is active in direct messages

all_users = set()
for channel in channels:
    users_in_channel = get_users_in_channel(channel)
    for user in users_in_channel:
        all_users.add(user)

user_dm_counts = {}

for user in all_users:
    inbox = read_inbox(user)
    for message in inbox:
        # Only count messages where the user is the sender (outgoing DMs)
        if message.sender == user:
            if user in user_dm_counts:
                user_dm_counts[user] += 1
            else:
                user_dm_counts[user] = 1

if len(user_dm_counts) == 0:
    raise ValueError("No messages found in any user inboxes.")

max_dm_count = max(user_dm_counts.values())
most_active_dm_users = [user for user, count in user_dm_counts.items() if count == max_dm_count]

most_active_user = most_active_dm_users[0]

send_direct_message(most_active_user, "Congrats on being the most active user!")
